"""
This module contains describes database schemas.

The models mirror the production schema exactly (nullability, identity
columns, constraint names), so ``alembic check`` stays clean against it.
"""

from sqlalchemy import (
    REAL,
    BigInteger,
    Column,
    Date,
    DateTime,
    ForeignKey,
    Identity,
    Integer,
    Text,
    func,
    text,
)
from sqlalchemy.orm import DeclarativeBase


class Base(DeclarativeBase):
    """This class is the represent declare base class for all tables"""

    pass


def identity_id(**kwargs) -> Column:
    """Primary key generated by the database (GENERATED ALWAYS AS IDENTITY)."""

    return Column(
        BigInteger, Identity(always=True), primary_key=True, autoincrement=True, **kwargs
    )


class Chat(Base):
    """This class is the represent declare table chats"""

    __tablename__ = "chats"
    __table_args__ = {"comment": "Chat table where the bot is running"}

    chat_id = Column(BigInteger, primary_key=True, autoincrement=False)
    date = Column(DateTime(timezone=True), nullable=False)
    delta = Column(Integer, nullable=False)
    # First day of the month whose survey results were last published.
    survey_period = Column(Date)
    # IANA zone the chat's admins enter and read dates in.
    timezone = Column(Text, nullable=False, server_default=text("'Europe/Moscow'"))


class History(Base):
    """This class is the represent declare table history"""

    __tablename__ = "history"

    id = identity_id()
    chat_id = Column(BigInteger, nullable=False)
    hunter = Column(Text, nullable=False)
    game = Column(Text, nullable=False)
    date = Column(DateTime(timezone=True), server_default=func.now(), nullable=False)
    platform = Column(Text, server_default=text("'Playstation'"))
    user_id = Column(BigInteger)
    avatar_date = Column(DateTime(timezone=True))


class Platinum(Base):
    """This class is the represent declare table platinum"""

    __tablename__ = "platinum"

    id = identity_id(comment="Unique ID")
    chat_id = Column(BigInteger, nullable=False)
    hunter = Column(Text, nullable=False)
    game = Column(Text, nullable=False)
    platform = Column(Text, server_default=text("'Playstation'"))
    photo_id = Column(Text, nullable=False)
    user_id = Column(BigInteger)


class Scores(Base):
    """This class is the represent declare table scores"""

    __tablename__ = "scores"

    id = identity_id()
    trophy_id = Column(
        BigInteger, ForeignKey(History.id, name="history"), nullable=False
    )
    user_id = Column(BigInteger, nullable=False)
    picture = Column(Integer)
    game = Column(Integer)
    difficulty = Column(Integer)


class Surveys(Base):
    """This class is the represent declare table surveys"""

    __tablename__ = "surveys"

    trophy_id = Column(
        BigInteger,
        ForeignKey(History.id, name="trophy"),
        nullable=False,
        primary_key=True,
        autoincrement=False,
    )
    picture = Column(REAL)
    game = Column(REAL)
    difficulty = Column(REAL)
